	return panel, {}, false
end

end

__modules['components.PlayerSelect'] = function()
--!strict
-- components/PlayerSelect.lua — single + multi player picker.
-- Same box/popover shell as Dropdown, but the menu lists Players:GetPlayers()
-- live (refetched on every open) with a headshot thumbnail, display name and
-- @username per row. Selection is tracked by UserId so it round-trips through
-- config Flags; :Get() always resolves live against the current player list,
-- so a player who leaves quietly drops out instead of leaving a stale handle.

local Players = game:GetService("Players")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Field = __require("components.Field")

local function hover(button: GuiButton, base: Color3, over: Color3)
	button.MouseEnter:Connect(function()
		Tween.play(button, Tween.Fast, { BackgroundColor3 = over })
	end)
	button.MouseLeave:Connect(function()
		Tween.play(button, Tween.Fast, { BackgroundColor3 = base })
	end)
end

local function displayName(p: Player): string
	if p.DisplayName ~= "" and p.DisplayName ~= p.Name then
		return p.DisplayName
	end
	return p.Name
end

local function toId(v: any): number?
	if typeof(v) == "Instance" and v:IsA("Player") then
		return v.UserId
	elseif type(v) == "number" then
		return v
	end
	return nil
end

local function build(ctx: any, opts: any, multi: boolean)
	local colors = Theme.Colors
	local placeholder = opts.Placeholder or (multi and "Select players..." or "Select a player...")
	local stack = opts.Stack == true

	local singleId: number? = toId(opts.Default)
	local selected: { [number]: boolean } = {}
	if multi and type(opts.Default) == "table" then
		for _, v in opts.Default do
			local id = toId(v)
			if id then
				selected[id] = true
			end
		end
	end

	local f = Field.new(ctx, opts, stack)

	-- box ────────────────────────────────────────────────────────────────────
	local box = Create("TextButton", {
		Name = "PlayerSelect",
		AutoButtonColor = false,
		Text = "",
		Size = stack and UDim2.new(1, 0, 0, 32) or UDim2.fromOffset(opts.Width or 160, 32),
		BackgroundColor3 = colors.control,
		LayoutOrder = 2,
		Parent = stack and f.field or f.row,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 8, 0, 12),
	})
	local boxStroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke

	local valLabel = Create("TextLabel", {
		Name = "Value",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 1, 0),
		Text = placeholder,
		TextColor3 = colors.text_muted,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = box,
	})

	local chevron = Icons.new("caret", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0);
	(chevron :: any).Parent = box

	-- menu ─────────────────────────────────────────────────────────────────── (parented to overlay on open)
	local menu = Create("CanvasGroup", {
		Name = "PlayerMenu",
		Visible = false,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.fromOffset(230, 0),
		BackgroundColor3 = colors.pop,
		ClipsDescendants = true,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
		Create.padding(5),
		Create.listLayout({ Padding = UDim.new(0, 2) }),
		Create("UISizeConstraint", { MaxSize = Vector2.new(math.huge, 260) }),
	})

	local function selectedPlayers(): { Player }
		local list = {}
		for _, p in Players:GetPlayers() do
			if selected[p.UserId] then
				table.insert(list, p)
			end
		end
		return list
	end

	local function valueLabelText(): (string, boolean)
		if multi then
			local names = {}
			for _, p in selectedPlayers() do
				table.insert(names, displayName(p))
			end
			if #names == 0 then
				return placeholder, false
			end
			return table.concat(names, ", "), true
		else
			local p = singleId and Players:GetPlayerByUserId(singleId)
			if not p then
				return placeholder, false
			end
			return displayName(p), true
		end
	end

	local function relabel()
		local text, hasVal = valueLabelText()
		valLabel.Text = text
		valLabel.TextColor3 = hasVal and colors.text or colors.text_muted
	end

	local function fireCallback()
		if not opts.Callback then
			return
		end
		if multi then
			task.spawn(opts.Callback, selectedPlayers())
		else
			task.spawn(opts.Callback, singleId and Players:GetPlayerByUserId(singleId) or nil)
		end
	end

	local rebuild -- fwd
	local function pick(p: Player)
		if multi then
			selected[p.UserId] = not selected[p.UserId] or nil
			relabel()
			rebuild()
		else
			singleId = p.UserId
			relabel()
			ctx:ClosePopover()
		end
		fireCallback()
	end

	rebuild = function()
		for _, child in menu:GetChildren() do
			if child:IsA("GuiButton") or child:IsA("TextLabel") then
				child:Destroy()
			end
		end

		local players = Players:GetPlayers()
		if #players == 0 then
			Create("TextLabel", {
				Name = "Empty",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 28),
				Text = "No players online",
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				Parent = menu,
			})
			return
		end

		for i, p in players do
			local sel = multi and selected[p.UserId] == true or (not multi and singleId == p.UserId)

			local row = Create("TextButton", {
				Name = p.Name,
				AutoButtonColor = false,
				Text = "",
				BackgroundColor3 = colors.control_hi,
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.Y,
				Size = UDim2.new(1, 0, 0, 0),
				LayoutOrder = i,
				Parent = menu,
			}, {
				Create.corner(6),
				Create.padding(6, 8),
				Create.listLayout({
					FillDirection = Enum.FillDirection.Horizontal,
					VerticalAlignment = Enum.VerticalAlignment.Center,
					Padding = UDim.new(0, 9),
				}),
			})

			local tickHolder = Create("Frame", {
				Name = "Tick",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(15, 15),
				LayoutOrder = 1,
				Parent = row,
			})
			local tick = Icons.new("check", 14, ctx.Accent)
			tick.Visible = sel;
			(tick :: any).Parent = tickHolder

			-- avatar: accent-tinted placeholder with a generic icon, swapped for the
			-- real headshot once GetUserThumbnailAsync resolves (it's a network call,
			-- so it runs off-thread and never blocks the menu from opening).
			local avatar = Create("Frame", {
				Name = "Avatar",
				Size = UDim2.fromOffset(28, 28),
				BackgroundColor3 = ctx.Accent,
				ClipsDescendants = true,
				LayoutOrder = 2,
				Parent = row,
			}, {
				Create.corner(8),
			})
			local avatarIcon = Icons.new("avatar", 16, colors.white)
			avatarIcon.AnchorPoint = Vector2.new(0.5, 0.5)
			avatarIcon.Position = UDim2.fromScale(0.5, 0.5);
			(avatarIcon :: any).Parent = avatar

			task.spawn(function()
				local ok, content = pcall(
					Players.GetUserThumbnailAsync,
					Players,
					p.UserId,
					Enum.ThumbnailType.HeadShot,
					Enum.ThumbnailSize.Size48x48
				)
				if ok and avatar.Parent then
					avatarIcon.Visible = false
					Create("ImageLabel", {
						Name = "Image",
						BackgroundTransparency = 1,
						Size = UDim2.fromScale(1, 1),
						Image = content,
						Parent = avatar,
					})
				end
			end)

			local names = Create("Frame", {
				Name = "Names",
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.XY,
				Size = UDim2.new(0, 0, 0, 0),
				LayoutOrder = 3,
				Parent = row,
			}, {
				Create.listLayout({ Padding = UDim.new(0, 1) }),
			})

			Create("TextLabel", {
				Name = "Display",
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = displayName(p),
				TextColor3 = sel and colors.text or colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				LayoutOrder = 1,
				Parent = names,
			})
			Create("TextLabel", {
				Name = "Username",
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = "@" .. p.Name,
				TextColor3 = colors.text_dim,
				TextSize = 11,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				LayoutOrder = 2,
				Parent = names,
			})

			row.MouseEnter:Connect(function()
				Tween.play(row, Tween.Fast, { BackgroundTransparency = 0 })
			end)
			row.MouseLeave:Connect(function()
				Tween.play(row, Tween.Fast, { BackgroundTransparency = 1 })
			end)
			row.Activated:Connect(function()
				pick(p)
			end)
		end
	end

	local function setOpenVisual(open: boolean)
		Tween.play(boxStroke, Tween.Fast, { Color = open and ctx.Accent or colors.border })
		Tween.play(chevron, Tween.Spin, { Rotation = open and 180 or 0 })
	end

	box.Activated:Connect(function()
		if ctx:IsOpen(menu) then
			ctx:ClosePopover()
			return
		end
		rebuild()
		menu.Size = UDim2.fromOffset(math.max(box.AbsoluteSize.X, 230), 0)
		setOpenVisual(true)
		ctx:OpenPopover(menu, box, function()
			setOpenVisual(false)
		end)
	end)
	hover(box, colors.control, colors.control_hi)

	relabel()

	local handle = {}
	function handle:Get(): any
		if multi then
			return selectedPlayers()
		end
		return singleId and Players:GetPlayerByUserId(singleId) or nil
	end
	function handle:Set(value: any)
		if multi then
			selected = {}
			if type(value) == "table" then
				for _, v in value do
					local id = toId(v)
					if id then
						selected[id] = true
					end
				end
			end
		else
			singleId = toId(value)
		end
		relabel()
		if ctx:IsOpen(menu) then
			rebuild()
		end
		fireCallback()
	end

	return f.field, handle, true
end

return build

end

__modules['components.Section'] = function()
--!strict
-- components/Section.lua — a nested collapsible group (indented, left rule).
-- Returns the section frame plus the inner body that controls mount into.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Collapse = __require("util.Collapse")

return function(ctx: any, opts: any): (Frame, Frame)
	local colors = Theme.Colors
	local collapsed = opts.Collapsed == true

	local section = Create("Frame", {
		Name = "Section",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({}),
	})

	-- No UIListLayout on the header: a layout-managed child won't render its
	-- Rotation, so the chevron is positioned manually to keep it free to spin.
	local head = Create("TextButton", {
		Name = "Head",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = section,
	}, {
		Create.padding(9, 2),
	})

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -18, 0, 0), -- leaves room for the chevron flush right
		Text = opts.Title or "Section",
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = head,
	})

	local chevron = Icons.new("chev", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0)
	chevron.Rotation = collapsed and 180 or 0;
	(chevron :: any).Parent = head

	local bodyWrap = Create("Frame", {
		Name = "BodyWrap",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	})

	local body = Create("Frame", {
		Name = "Body",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(14, 0),
		Size = UDim2.new(1, -14, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = bodyWrap,
	}, {
		Create.padding(1, 0, 8, 0),
		Create.listLayout({}),
	})

	-- Left rule. Scale height (1,0 on Y) fills bodyWrap natively; scale-sized
	-- children are ignored by AutomaticSize, so the rule can't feed back into
	-- bodyWrap's height and cause AbsoluteSizeChanged re-entrancy.
	Create("Frame", {
		Name = "Rule",
		Position = UDim2.fromOffset(2, 1),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border,
		BorderSizePixel = 0,
		Parent = bodyWrap,
	})

	-- Clipping holder owns the body's height so it slides open/closed.
	local holder, setCollapsed = Collapse.wrap(bodyWrap, collapsed)
	holder.LayoutOrder = 2
	holder.Parent = section

	head.Activated:Connect(function()
		collapsed = not collapsed
		Tween.play(chevron, Tween.Spin, { Rotation = collapsed and 180 or 0 })
		setCollapsed(collapsed, true)
	end)

	return section, body
end

end

__modules['components.Slider'] = function()
--!strict
-- components/Slider.lua — 6px pill track, accent fill, 15px white knob.
-- Live drag via UserInputService (no tween), clamped + stepped.

local UserInputService = game:GetService("UserInputService")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")

local function clamp(v: number, a: number, b: number): number
	return math.max(a, math.min(b, v))
end

local function format(v: number, suffix: string): string
	return ("%g"):format(v) .. suffix
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local where = Log.where("Slider", opts.Name)
	Log.field(where, "Min", opts.Min, "number")
	Log.field(where, "Max", opts.Max, "number")
	Log.field(where, "Step", opts.Step, "number")

	local min = opts.Min or 0
	local max = opts.Max or 100
	-- An inverted or collapsed range makes every position map to the same value
	-- (render()/snap() guard the maths, but the control would be dead). Warn and
	-- fall back to a sane [min, min+1] so it's at least usable.
	if min >= max then
		Log.warn(where, ("Min (%s) must be less than Max (%s) — using [%s, %s]."):format(
			("%g"):format(min), ("%g"):format(max), ("%g"):format(min), ("%g"):format(min + 1)))
		max = min + 1
	end
	local step = opts.Step or 1
	if step < 0 then
		Log.warn(where, ("Step (%s) can't be negative — using 1."):format(("%g"):format(step)))
		step = 1
	end
	local suffix = opts.Suffix or ""
	local value = clamp(opts.Default or min, min, max)

	local f = Field.new(ctx, opts, true)

	local valBox = Create("TextLabel", {
		Name = "Value",
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(38, 22),
		BackgroundColor3 = colors.control,
		Text = format(value, suffix),
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Medium,
		LayoutOrder = 2,
		Parent = f.row,
	}, {
		Create.corner(6),
		Create.stroke(colors.border),
		Create.padding(2, 9),
		Create("UISizeConstraint", { MinSize = Vector2.new(38, 22) }),
	})

	local track = Create("TextButton", {
		Name = "Slider",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.new(1, 0, 0, 6),
		BackgroundColor3 = colors.toggle_off,
		LayoutOrder = 2,
		Parent = f.field,
	}, {
		Create.corner(999),
	})

	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = ctx.Accent,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(15, 15),
		BackgroundColor3 = colors.white,
		ZIndex = 2,
		Parent = track,
	}, {
		Create.corner(999),
		Create("UIScale", {}),
	})
	local knobScale = knob:FindFirstChildOfClass("UIScale") :: UIScale

	local function snap(v: number): number
		-- guard a zero step so a bad config can't divide-by-zero. (Explicit if,
		-- not `and/or` — the snapped value can legitimately be 0, which the idiom
		-- would mistake for false and fall through to v.)
		if step > 0 then
			return math.round(v / step) * step
		end
		return v
	end

	local function render()
		-- guard min==max (degenerate range) so the ratio never produces NaN
		local span = max - min
		local pct = span ~= 0 and (value - min) / span or 0
		fill.Size = UDim2.fromScale(pct, 1)
		knob.Position = UDim2.fromScale(pct, 0.5)
		valBox.Text = format(value, suffix)
	end

	local function setFromX(x: number)
		local span = track.AbsoluteSize.X
		local pct = span > 0 and clamp((x - track.AbsolutePosition.X) / span, 0, 1) or 0
		value = clamp(snap(min + pct * (max - min)), min, max)
		render()
		if opts.Callback then
			task.spawn(opts.Callback, value)
		end
	end

	-- The move/release listeners are global (UserInputService), so they're only
	-- connected for the duration of a drag and torn down on release. That avoids
	-- N idle sliders each leaking a permanent listener that fires on every mouse
	-- move and survives Window:Destroy.
	local dragConns: { RBXScriptConnection } = {}
	local function endDrag()
		for _, c in dragConns do
			c:Disconnect()
		end
		table.clear(dragConns)
		Tween.play(knobScale, Tween.Spring, { Scale = 1 }) -- settle back on release
	end
	track.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			if #dragConns > 0 then
				return
			end
			Tween.play(knobScale, Tween.Spring, { Scale = 1.3 }) -- grow while grabbed
			setFromX(input.Position.X)
			table.insert(dragConns, UserInputService.InputChanged:Connect(function(move)
				if move.UserInputType == Enum.UserInputType.MouseMovement
					or move.UserInputType == Enum.UserInputType.Touch then
					setFromX(move.Position.X)
				end
			end))
			table.insert(dragConns, UserInputService.InputEnded:Connect(function(up)
				if up.UserInputType == Enum.UserInputType.MouseButton1
					or up.UserInputType == Enum.UserInputType.Touch then
					endDrag()
				end
			end))
		end
	end)

	ctx:RegisterAccent(function(accent)
		fill.BackgroundColor3 = accent
	end)
	render()

	local handle = {}
	function handle:Get(): number
		return value
	end
	function handle:Set(v: number)
		value = clamp(snap(v), min, max)
		render()
		if opts.Callback then
			task.spawn(opts.Callback, value)
		end
	end

	return f.field, handle, true
end

end

__modules['components.Tab'] = function()
--!strict
-- components/Tab.lua — a sidebar nav button + a two-column content page.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Log = __require("util.Log")
local Group = __require("components.Group")

local M = Theme.Metrics

local function newColumn(order: number): Frame
	return Create("Frame", {
		Name = "Column",
		BackgroundTransparency = 1,
		AnchorPoint = order == 2 and Vector2.new(1, 0) or Vector2.new(0, 0),
		Position = order == 2 and UDim2.fromScale(1, 0) or UDim2.fromScale(0, 0),
		Size = UDim2.new(0.5, -(M.columnGap / 2), 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({ Padding = UDim.new(0, M.groupGap) }),
	})
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors

	-- nav button ──────────────────────────────────────────────────────────
	local button = Create("TextButton", {
		Name = "Nav_" .. (opts.Name or "Tab"),
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(M.navButton, M.navButton),
		BackgroundColor3 = colors.accent,
		BackgroundTransparency = 1,
	}, {
		Create.corner(M.navRadius),
	})

	-- Accent glow under the active button — the CSS `box-shadow: 0 6px 16px -4px
	-- accent`. A soft accent-tinted shadow image sitting behind the button
	-- (ZIndex 0, so the overflow haloes out past the button's rounded fill).
	local glow = Create("ImageLabel", {
		Name = "Glow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.62),
		Size = UDim2.fromOffset(M.navButton + 26, M.navButton + 26),
		BackgroundTransparency = 1,
		Image = "rbxassetid://6014261993",
		ImageColor3 = ctx.Accent,
		ImageTransparency = 1,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = Rect.new(49, 49, 450, 450),
		ZIndex = 0,
		Parent = button,
	})

	local icon = Icons.new(opts.Icon or "gear", M.navIcon, colors.text_dim)
	icon.AnchorPoint = Vector2.new(0.5, 0.5)
	icon.Position = UDim2.fromScale(0.5, 0.5);
	(icon :: any).Parent = button
	local iconScale = Create("UIScale", { Parent = icon })

	-- content page ────────────────────────────────────────────────────────
	local page = Create("Frame", {
		Name = "Page_" .. (opts.Name or "Tab"),
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
	})
	local columns = Create("Frame", {
		Name = "Columns",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = page,
	})
	local col1 = newColumn(1)
	col1.Parent = columns
	local col2 = newColumn(2)
	col2.Parent = columns

	-- Scale height (1,0 on Y) so the divider fills the column block natively.
	-- Roblox excludes scale-sized children from a parent's AutomaticSize, so this
	-- can't feed back into `columns` and trigger AbsoluteSizeChanged re-entrancy
	-- (the old signal-driven offset height oscillated on subpixel rounding).
	Create("Frame", {
		Name = "ColDivider",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border_soft,
		BorderSizePixel = 0,
		Parent = columns,
	})

	-- nav state ──────────────────────────────────────────────────────────
	local active = false
	local hovering = false
	-- Crossfade both colour and transparency in a single tween. The old code
	-- snapped BackgroundColor3 to white instantly while the fill was still
	-- opaque (and snapped transparency to 0 on activate), so a switched-off tab
	-- showed a solid flash for one frame before fading. Keeping the colour on
	-- the accent while the fill fades out means there's no intermediate solid
	-- colour to flash — the accent simply fades in / out.
	local function paint(animate: boolean?)
		local goal
		local glowGoal = { ImageTransparency = active and 0.45 or 1 }
		if active then
			goal = { BackgroundColor3 = ctx.Accent, BackgroundTransparency = 0 }
			Icons.tint(icon, colors.white)
		else
			goal = {
				-- idle (transparency 1) keeps the accent so the fade-out is a
				-- pure accent fade; only the faint hover fill uses white.
				BackgroundColor3 = hovering and colors.white or ctx.Accent,
				BackgroundTransparency = hovering and 0.92 or 1,
			}
			Icons.tint(icon, hovering and colors.text_muted or colors.text_dim)
		end
		if animate == false then
			for key, value in goal do
				(button :: any)[key] = value
			end
			glow.ImageTransparency = glowGoal.ImageTransparency
		else
			Tween.play(button, Tween.Fast, goal)
			Tween.play(glow, Tween.Fast, glowGoal)
		end
	end
	button.MouseEnter:Connect(function()
		hovering = true
		if not active then
			paint()
		end
	end)
	button.MouseLeave:Connect(function()
		hovering = false
		if not active then
			paint()
		end
	end)
	ctx:RegisterAccent(function()
		glow.ImageColor3 = ctx.Accent
		if active then
			button.BackgroundColor3 = ctx.Accent
		end
	end)

	local tab = {
		button = button,
		page = page,
	}
	function tab:_setActive(value: boolean)
		local becameActive = value and not active
		active = value
		page.Visible = value
		paint()
		if becameActive then
			iconScale.Scale = 0.8
			Tween.play(iconScale, Tween.Spring, { Scale = 1 }) -- pop on select
			-- ease the page up into place so switching tabs settles instead of
			-- hard-cutting (rest position is set by Window; nudge down, slide back)
			local rest = page.Position
			page.Position = rest + UDim2.fromOffset(0, 10)
			Tween.play(page, Tween.Normal, { Position = rest })
		end
	end
	function tab:CreateGroup(groupOpts: any)
		if groupOpts ~= nil and type(groupOpts) ~= "table" then
			Log.fail("CreateGroup", ("options must be a table like { Title = ..., Column = 1 }, got %s")
				:format(typeof(groupOpts)))
		end
		-- Column is 1 (left) or 2 (right). A stray value (e.g. Column = 3, or a
		-- string) would silently land the group in the left column — warn and
		-- fall back so the author knows their column choice was ignored.
		local column = groupOpts and groupOpts.Column
		if column ~= nil and column ~= 1 and column ~= 2 then
			Log.warn(Log.where("CreateGroup", groupOpts and groupOpts.Title),
				("Column must be 1 (left) or 2 (right), got %s — using column 1."):format(tostring(column)))
		end
		local target = (column == 2) and col2 or col1
		return Group(ctx, target, groupOpts or {})
	end

	return tab
end

end

__modules['components.Toggle'] = function()
--!strict
-- components/Toggle.lua — 42×23 pill, 17px knob, +19px travel.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Field = __require("components.Field")

local OFF_POS = UDim2.fromOffset(3, 3)
local ON_POS = UDim2.fromOffset(22, 3) -- 3 + 19px travel

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local f = Field.new(ctx, opts)
	local state = opts.Default == true

	local track = Create("TextButton", {
		Name = "Toggle",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(42, 23),
		BackgroundColor3 = colors.toggle_off,
		LayoutOrder = 2,
		Parent = f.row,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		Size = UDim2.fromOffset(17, 17),
		Position = OFF_POS,
		BackgroundColor3 = colors.knob,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local function paint(animate: boolean)
		local trackColor = state and ctx.Accent or colors.toggle_off
		local knobColor = state and colors.white or colors.knob
		local pos = state and ON_POS or OFF_POS
		if animate then
			Tween.play(track, Tween.Normal, { BackgroundColor3 = trackColor })
			Tween.play(knob, Tween.Normal, { BackgroundColor3 = knobColor })
			Tween.play(knob, Tween.Spring, { Position = pos }) -- slight overshoot on the slide
		else
			track.BackgroundColor3 = trackColor
			knob.BackgroundColor3 = knobColor
			knob.Position = pos
		end
	end

	local handle = {}
	function handle:Get(): boolean
		return state
	end
	function handle:Set(value: boolean)
		state = value == true
		paint(true)
		if opts.Callback then
			task.spawn(opts.Callback, state)
		end
	end

	track.Activated:Connect(function()
		handle:Set(not state)
	end)

	ctx:RegisterAccent(function()
		paint(false)
	end)

	return f.field, handle, true
end

end

__modules['components.Window'] = function()
--!strict
-- components/Window.lua — the window shell: titlebar, sidebar, scrolling content,
-- status bar and overlay. Owns the Context, the tab list, notifications and the
-- live accent. Mounts a ScreenGui to the LocalPlayer's PlayerGui.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Context = __require("util.Context")
local Config = __require("util.Config")
local Log = __require("util.Log")
local Tab = __require("components.Tab")
local Notify = __require("components.Notify")

local M = Theme.Metrics

return function(opts: any)
	opts = opts or {}
	local colors = Theme.Colors

	-- Validate the window options up front so a wrong type surfaces here (naming
	-- the field) rather than as a mystery error much later when it's first used.
	Log.field("CreateWindow", "Title", opts.Title, "string")
	Log.field("CreateWindow", "ToggleKey", opts.ToggleKey, "EnumItem")
	Log.field("CreateWindow", "Accent", opts.Accent, "Color3")
	Log.field("CreateWindow", "ConfigFolder", opts.ConfigFolder, "string")

	-- where configs are saved on disk + which key shows/hides the window
	local configFolder = opts.ConfigFolder or "coreui"
	local toggleKey: Enum.KeyCode = opts.ToggleKey or Enum.KeyCode.RightShift
	local notificationsEnabled = true
	-- UserInputService connections live past the ScreenGui's lifetime, so they're
	-- tracked here and disconnected by Window:Destroy.
	local connections: { RBXScriptConnection } = {}

	-- ── ScreenGui + window frame ────────────────────────────────────────────
	local screenGui = Create("ScreenGui", {
		Name = "coreui",
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})

	-- CanvasGroup (not Frame) so minimize/close can fade the *entire* window as a
	-- single unit via GroupTransparency — a plain Frame can only fade its own
	-- background, which is why scaling-then-hiding looked like a snap.
	local main = Create("CanvasGroup", {
		Name = "Window",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(M.windowWidth, M.windowHeight),
		BackgroundColor3 = colors.bg,
		ClipsDescendants = true,
		Parent = screenGui,
	}, {
		Create.corner(M.windowRadius),
		Create.stroke(Color3.new(0, 0, 0)),
		Create("UIScale", {}),
	})
	local mainScale = main:FindFirstChildOfClass("UIScale") :: UIScale

	-- ── drop shadow ─────────────────────────────────────────────────────────
	-- The reference window floats: `box-shadow: 0 30px 80px -20px rgba(0,0,0,.8)`.
	-- A 9-sliced soft-shadow image behind the window gives it that elevation. It
	-- lives in the ScreenGui (a sibling behind `main`, not a child — `main`
	-- clips, and the shadow has to bleed past the window edges) and tracks the
	-- window as it's dragged / resized.
	-- A *radial* shadow image (one smooth centre→edge gradient) stretched behind
	-- the window. A 9-slice shadow only softens its ~49px border and stretches a
	-- solid core, so it reads as a hard dark band that ends abruptly — this fades
	-- gradually the whole way out instead. Big PAD = the gradient's soft tail is
	-- what shows past the window edge; the dark middle stays hidden behind it.
	local SHADOW_PAD = 60 -- how far the soft tail bleeds past each edge (bigger = more gradual falloff)
	local SHADOW_DROP = 8  -- nudge down so the light reads as coming from above (kept small so the bottom doesn't read heavy)
	local SHADOW_T = 0.82  -- resting image transparency (high = faint, barely-there shadow)
	local shadow = Create("ImageLabel", {
		Name = "Shadow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = main.Position,
		Size = UDim2.fromOffset(M.windowWidth + SHADOW_PAD, M.windowHeight + SHADOW_PAD),
		BackgroundTransparency = 1,
		Image = "rbxassetid://1316045217", -- soft radial blur
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = 1, -- faded in on mount, alongside the window
		ScaleType = Enum.ScaleType.Stretch,
		ZIndex = 0,
		Parent = screenGui,
	})
	local function syncShadow()
		shadow.Position = main.Position + UDim2.fromOffset(0, SHADOW_DROP)
		shadow.Size = UDim2.new(
			main.Size.X.Scale, main.Size.X.Offset + SHADOW_PAD,
			main.Size.Y.Scale, main.Size.Y.Offset + SHADOW_PAD
		)
	end
	main:GetPropertyChangedSignal("Position"):Connect(syncShadow)
	main:GetPropertyChangedSignal("Size"):Connect(syncShadow)

	-- Never exceed the viewport — on small screens the window shrinks to fit
	-- (centered) instead of spilling content off the right/bottom edge.
	local function fitWindow()
		local vp = screenGui.AbsoluteSize
		if vp.X <= 0 then
			return
		end
		main.Size = UDim2.fromOffset(
			math.min(M.windowWidth, vp.X - 24),
			math.min(M.windowHeight, vp.Y - 24)
		)
	end
	screenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitWindow)
	task.defer(fitWindow)

	-- ── titlebar ───────────────────────────────────────────────────────────
	local titlebar = Create("Frame", {
		Name = "Titlebar",
		Size = UDim2.new(1, 0, 0, M.titlebar),
		BackgroundColor3 = colors.chrome,
		Parent = main,
	}, {
		-- Round the top corners to match the window. main's ClipsDescendants
		-- clips to a rectangle (not the rounded shape), so without this the
		-- square chrome corners poke past main's rounded corners.
		Create.corner(M.windowRadius),
		Create("Frame", { -- square off the bottom so only the top corners round
			Name = "SquareFill",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, M.windowRadius),
			BackgroundColor3 = colors.chrome,
			BorderSizePixel = 0,
		}),
		Create("Frame", { -- bottom hairline
			Name = "Border",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = colors.border_soft,
			BorderSizePixel = 0,
		}),
		Create("Frame", { -- top inset highlight — the CSS `inset` lit edge that
			Name = "Highlight",            -- catches light and lifts the window
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = colors.white,
			BackgroundTransparency = 0.94,
			BorderSizePixel = 0,
		}),
	})

	-- logo
	local logo = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(26, 26),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, M.sidebar / 2, 0.5, 0),
		BackgroundColor3 = colors.accent,
		Parent = titlebar,
	}, {
		Create.corner(8),
	})
	local logoGradient = Create("UIGradient", {
		Color = ColorSequence.new(colors.accent_2, colors.accent),
		Rotation = 135,
		Parent = logo,
	})
	Create("Frame", { -- ring
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(13, 13),
		BackgroundTransparency = 1,
		Parent = logo,
	}, { Create.corner(999), Create.stroke(colors.white, 2) })
	Create("Frame", { -- dot
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(5, 5),
		BackgroundColor3 = colors.white,
		Parent = logo,
	}, { Create.corner(999) })

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = opts.Title or "coreui",
		TextColor3 = colors.text,
		TextSize = 16,
		FontFace = Theme.Font.Bold,
		Parent = titlebar,
	})

	-- Right cluster holds a collapsible search field followed by the window
	-- buttons; the horizontal list keeps them packed against the right edge.
	local rightCluster = Create("Frame", {
		Name = "RightCluster",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -18, 0.5, 0),
		Size = UDim2.fromOffset(0, M.titlebar),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Parent = titlebar,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- search field — hidden until the search button is clicked. A CanvasGroup so
	-- its width can slide open while every child fades in together; ClipsDescendants
	-- keeps the icon/box from spilling out while it's narrower than its content.
	local SEARCH_W = 180
	local searchField = Create("CanvasGroup", {
		Name = "Search",
		Visible = false,
		Size = UDim2.fromOffset(SEARCH_W, 30),
		BackgroundColor3 = colors.control,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = rightCluster,
	}, {
