	local maximized = false
	winBtns.max.Activated:Connect(function()
		maximized = not maximized
		if maximized then
			local vp = screenGui.AbsoluteSize
			Tween.play(main, Tween.Normal, {
				Size = UDim2.fromOffset(
					math.max(M.windowWidth, vp.X - 24),
					math.max(M.windowHeight, vp.Y - 24)
				),
			})
		else
			local vp = screenGui.AbsoluteSize
			Tween.play(main, Tween.Normal, {
				Size = UDim2.fromOffset(
					math.min(M.windowWidth, vp.X - 24),
					math.min(M.windowHeight, vp.Y - 24)
				),
			})
		end
	end)

	-- ── close ────────────────────────────────────────────────────────────────
	winBtns.close.Activated:Connect(function()
		-- same shrink+fade as minimize, but disable the gui once it's gone
		Tween.play(mainScale, Tween.MenuOut, { Scale = 0.9 })
		Tween.play(shadow, Tween.MenuOut, { ImageTransparency = 1 })
		local t = Tween.play(main, Tween.MenuOut, { GroupTransparency = 1 })
		t.Completed:Once(function()
			screenGui.Enabled = false
			mainScale.Scale = 1 -- reset in case it's ever re-enabled
			main.GroupTransparency = 0
			shadow.ImageTransparency = SHADOW_T
		end)
	end)

	function window:CreateTab(tabOpts: any)
		if tabOpts ~= nil and type(tabOpts) ~= "table" then
			Log.fail("CreateTab", ("options must be a table like { Name = ..., Icon = ... }, got %s"
				.. " — if you meant a title, write CreateTab({ Name = %s })")
				:format(typeof(tabOpts), type(tabOpts) == "string" and ('"%s"'):format(tabOpts) or "..."))
		end
		Log.field("CreateTab", "Name", tabOpts and tabOpts.Name, "string")
		Log.field("CreateTab", "Icon", tabOpts and tabOpts.Icon, "string")
		local tab = Tab(ctx, tabOpts or {})
		tab.button.Parent = nav
		tab.page.Parent = content

		-- Inset the page explicitly and size it to the scroll area's *visible*
		-- width (AbsoluteWindowSize excludes the scrollbar). This guarantees the
		-- right column keeps its margin regardless of executor quirks.
		tab.page.Position = UDim2.fromOffset(CONTENT_PAD_X, 0)
		local function fitPage()
			local avail = content.AbsoluteWindowSize.X
			if avail <= 0 then
				avail = content.AbsoluteSize.X
			end
			tab.page.Size = UDim2.new(0, math.max(0, avail - CONTENT_PAD_X * 2), 0, 0)
		end
		content:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPage)
		content:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(fitPage)
		task.defer(fitPage)

		local index = #tabs + 1
		tab.button.LayoutOrder = index
		table.insert(tabs, tab)
		tab.button.Activated:Connect(function()
			select(index)
		end)
		if index == 1 then
			select(1)
		end
		return tab
	end

	function window:Select(index: number)
		if type(index) ~= "number" or index < 1 or index > #tabs or index % 1 ~= 0 then
			Log.warn("Select", ("no tab #%s (there %s %d tab%s) — ignoring.")
				:format(tostring(index), #tabs == 1 and "is" or "are", #tabs, #tabs == 1 and "" or "s"))
			return
		end
		select(index)
	end

	function window:Notify(notifyOpts: any)
		if notifyOpts ~= nil and type(notifyOpts) ~= "table" then
			Log.fail("Notify", ("options must be a table like { Title = ..., Text = ... }, got %s")
				:format(typeof(notifyOpts)))
		end
		if not notificationsEnabled then
			return
		end
		Notify(ctx, toasts, notifyOpts)
	end

	function window:SetAccent(color: Color3)
		if typeof(color) ~= "Color3" then
			Log.fail("SetAccent", ("expects a Color3, got %s (try Color3.fromHex(\"7c5cff\"))")
				:format(typeof(color)))
		end
		ctx:SetAccent(color)
	end

	-- ── settings: theme / keybind / notifications ─────────────────────────────
	function window:SetToggleKey(key: Enum.KeyCode)
		if key ~= nil and typeof(key) ~= "EnumItem" then
			Log.fail("SetToggleKey", ("expects an Enum.KeyCode, got %s (try Enum.KeyCode.RightShift)")
				:format(typeof(key)))
		end
		toggleKey = key or Enum.KeyCode.Unknown
		restoreHintText.Text = toggleKey ~= Enum.KeyCode.Unknown
			and ("Press %s to show it again."):format(toggleKey.Name)
			or "Re-bind a toggle key to show it again."
	end

	function window:SetNotificationsEnabled(enabled: boolean)
		notificationsEnabled = enabled ~= false
	end

	-- ── settings: config persistence ──────────────────────────────────────────
	-- These read/write the flag registry (any control built with a `Flag`).
	window.ConfigSupported = Config.supported

	local function badConfigName(where: string, name: any): boolean
		if type(name) ~= "string" or name == "" then
			Log.warn(where, ("config name must be a non-empty string, got %s — ignoring.")
				:format(name == "" and '""' or typeof(name)))
			return true
		end
		return false
	end

	function window:SaveConfig(name: string): boolean
		if badConfigName("SaveConfig", name) then
			return false
		end
		local snapshot = ctx:GetConfig()
		local ok = Config.save(configFolder, name, snapshot)
		local n = 0
		for _ in snapshot do
			n += 1
		end
		print(("[coreui] SaveConfig(%q) -> %s  (%d flags)"):format(tostring(name), tostring(ok), n))
		return ok
	end
	function window:LoadConfig(name: string): boolean
		if badConfigName("LoadConfig", name) then
			return false
		end
		local data = Config.load(configFolder, name)
		print(("[coreui] LoadConfig(%q) -> %s"):format(tostring(name), tostring(data ~= nil)))
		if data then
			ctx:LoadConfig(data)
			return true
		end
		return false
	end
	function window:DeleteConfig(name: string): boolean
		if badConfigName("DeleteConfig", name) then
			return false
		end
		return Config.delete(configFolder, name)
	end
	function window:ListConfigs(): { string }
		return Config.list(configFolder)
	end

	-- ── teardown ───────────────────────────────────────────────────────────────
	-- Disconnect the lingering UserInputService listeners, then fade the window
	-- out and destroy the ScreenGui (close() only hides it; this fully unloads).
	function window:Destroy()
		Tween.play(mainScale, Tween.MenuOut, { Scale = 0.9 })
		Tween.play(shadow, Tween.MenuOut, { ImageTransparency = 1 })
		local t = Tween.play(main, Tween.MenuOut, { GroupTransparency = 1 })
		t.Completed:Once(function()
			for _, conn in connections do
				conn:Disconnect()
			end
			table.clear(connections)
			ctx:ClosePopover()
			screenGui:Destroy()
		end)
	end

	-- ── built-in Settings tab ───────────────────────────────────────────────────
	-- A drop-in panel: accent color, the toggle keybind, a notifications switch,
	-- and full config save / load / delete + auto-load. Call it LAST so the
	-- auto-load pass sees every flagged control your other tabs registered.
	function window:CreateSettingsTab(settingsOpts: any?)
		settingsOpts = settingsOpts or {}
		print(("[coreui] CreateSettingsTab: building (config supported=%s)"):format(tostring(Config.supported)))
		local tab = window:CreateTab({
			Name = settingsOpts.Name or "Settings",
			Icon = settingsOpts.Icon or "gear",
		})

		-- Interface ──────────────────────────────────────────────────────────────
		local iface = tab:CreateGroup({ Title = "Interface", Column = 1 })
		iface:Colorpicker({
			Name = "Accent Color",
			Desc = "Re-themes the whole UI.",
			Flag = "coreui_accent",
			Default = ctx.Accent,
			Callback = function(c)
				window:SetAccent(c)
			end,
		})
		iface:Keybind({
			Name = "Toggle UI",
			Desc = "Show or hide the window.",
			Flag = "coreui_togglekey",
			Default = toggleKey,
			Callback = function(k)
				window:SetToggleKey(k)
			end,
		})
		iface:Toggle({
			Name = "Notifications",
			Desc = "Show toast notifications.",
			Flag = "coreui_notifications",
			Default = true,
			Callback = function(on)
				window:SetNotificationsEnabled(on)
			end,
		})

		-- Configuration ────────────────────────────────────────────────────────────
		local cfg = tab:CreateGroup({ Title = "Configuration", Column = 2 })
		if not Config.supported then
			cfg:Paragraph({
				Title = "Unavailable",
				Body = "Your executor doesn't expose file functions, so configs can't "
					.. "be saved. Everything else here still works.",
			})
		else
			local nameBox = cfg:Input({ Name = "Config Name", Placeholder = "my config" })
			local list = cfg:Dropdown({
				Name = "Saved Configs",
				Placeholder = "None saved",
				Stack = true,
				Options = window:ListConfigs(),
			})
			local function refresh()
				list:SetOptions(window:ListConfigs())
			end

			cfg:ButtonRow({
				{
					Label = "Save",
					Callback = function()
						local n = nameBox:Get()
						if n == nil or n == "" then
							window:Notify({ Title = "Config", Text = "Enter a name first." })
							return
						end
						if window:SaveConfig(n) then
							refresh()
							list:Set(n)
							window:Notify({ Title = "Config", Text = ('Saved "%s".'):format(n) })
						else
							window:Notify({ Title = "Config", Text = "Save failed." })
						end
					end,
				},
				{
					Label = "Load",
					Callback = function()
						local n = list:Get()
						if not n then
							window:Notify({ Title = "Config", Text = "Pick a config to load." })
							return
						end
						if window:LoadConfig(n) then
							window:Notify({ Title = "Config", Text = ('Loaded "%s".'):format(n) })
						end
					end,
				},
			})
			cfg:ButtonRow({
				{
					Label = "Delete",
					Callback = function()
						local n = list:Get()
						if not n then
							return
						end
						window:DeleteConfig(n)
						refresh()
						window:Notify({ Title = "Config", Text = ('Deleted "%s".'):format(n) })
					end,
				},
				{ Label = "Refresh", Callback = refresh },
			})
			cfg:Toggle({
				Name = "Auto Load",
				Desc = "Apply the selected config on launch.",
				Default = Config.getAutoload(configFolder) ~= nil,
				Callback = function(on)
					Config.setAutoload(configFolder, on and list:Get() or nil)
				end,
			})

			-- Apply the auto-load config once the rest of the UI has finished
			-- building (this tab is meant to be created last, so all flags exist).
			task.defer(function()
				local auto = Config.getAutoload(configFolder)
				if auto then
					list:Set(auto)
					window:LoadConfig(auto)
				end
			end)
		end

		cfg:Divider()
		cfg:Button({
			Name = "Danger Zone",
			Label = "Unload coreui",
			Callback = function()
				window:Destroy()
			end,
		})

		local flagCount = 0
		for _ in ctx.Flags do
			flagCount += 1
		end
		print(("[coreui] CreateSettingsTab: done (%d flags registered)"):format(flagCount))
		return tab
	end

	-- mount — pop the window in from a touch smaller and faded so it eases in
	-- rather than just appearing
	mainScale.Scale = 0.92
	main.GroupTransparency = 1
	syncShadow()
	task.defer(function()
		Tween.play(mainScale, Tween.Pop, { Scale = 1 })
		Tween.play(main, Tween.Normal, { GroupTransparency = 0 })
		Tween.play(shadow, Tween.Normal, { ImageTransparency = SHADOW_T })
	end)

	local localPlayer = Players.LocalPlayer
	if localPlayer then
		screenGui.Parent = localPlayer:WaitForChild("PlayerGui")
	elseif RunService:IsStudio() then
		screenGui.Parent = game:GetService("CoreGui")
	end

	return window
end

end

__modules['util.Collapse'] = function()
--!strict
-- util/Collapse.lua — animate a frame collapsing/expanding by height.
--
-- Wraps an AutomaticSize.Y `content` frame in a ClipsDescendants holder whose
-- height is what actually animates. While open the holder tracks the content via
-- AutomaticSize.Y (so dynamically-added controls still grow it); during the
-- collapse/expand it switches to a manual offset height that we tween to/from 0.
-- The content keeps its natural size the whole time (clipping only hides it), so
-- the target height can be read straight off it even while collapsed.

local Tween = __require("util.Tween")
local Create = __require("util.Create")

local Collapse = {}

-- `content` must be (1, 0) wide with AutomaticSize.Y. Returns the holder to drop
-- into the surrounding layout, plus `set(collapsed, animate)`.
function Collapse.wrap(content: GuiObject, startCollapsed: boolean): (Frame, (boolean, boolean?) -> ())
	local holder = Create("Frame", {
		Name = "Collapse",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		AutomaticSize = startCollapsed and Enum.AutomaticSize.None or Enum.AutomaticSize.Y,
	})
	content.Parent = holder

	local collapsed = startCollapsed
	local activeTween: Tween? = nil

	local function set(value: boolean, animate: boolean?)
		if value == collapsed then
			return
		end
		collapsed = value
		if activeTween then
			activeTween:Cancel()
			activeTween = nil
		end

		if not animate then
			holder.AutomaticSize = value and Enum.AutomaticSize.None or Enum.AutomaticSize.Y
			holder.Size = UDim2.new(1, 0, 0, value and 0 or content.AbsoluteSize.Y)
			return
		end

		-- Hand height control to a manual offset for the duration of the tween.
		holder.AutomaticSize = Enum.AutomaticSize.None
		if value then
			-- collapse: freeze at the current rendered height, slide to 0
			holder.Size = UDim2.new(1, 0, 0, holder.AbsoluteSize.Y)
			activeTween = Tween.play(holder, Tween.Slide, { Size = UDim2.new(1, 0, 0, 0) })
		else
			-- expand: slide up to the content's natural height, then hand back to
			-- AutomaticSize so later content changes keep tracking
			local target = content.AbsoluteSize.Y
			local t = Tween.play(holder, Tween.Slide, { Size = UDim2.new(1, 0, 0, target) })
			activeTween = t
			t.Completed:Once(function(state)
				if state == Enum.PlaybackState.Completed and not collapsed then
					holder.AutomaticSize = Enum.AutomaticSize.Y
				end
			end)
		end
	end

	return holder, set
end

return Collapse

end

__modules['util.Config'] = function()
--!strict
-- util/Config.lua — executor filesystem layer for saving / loading configs.
--
-- Exploit executors expose global file functions (writefile / readfile / …) that
-- don't exist in Studio or live game clients. Everything here is feature-detected
-- and pcall-guarded so the library degrades gracefully (Config.supported = false)
-- instead of erroring where those globals are absent.
--
-- Layout on disk:  <folder>/configs/<name>.json   (one JSON blob per config)
--                  <folder>/autoload.txt          (name of the config to auto-load)

local HttpService = game:GetService("HttpService")

local Config = {}

-- Resolve executor file globals. Executors put these on the SHARED global env
-- (getgenv) — not the chunk env — so prefer that, then fall back to the ambient
-- global / _G. Everything is pcall-guarded: some sandboxes throw merely on
-- touching getgenv/getfenv, and a raw error here would kill the whole library at
-- require time (this module is required by Window).
local genv: any = nil
pcall(function()
	if type(getgenv) == "function" then
		genv = getgenv()
	end
end)

local function g(name: string): any
	-- 1) shared global env (getgenv)
	if type(genv) == "table" then
		local ok, v = pcall(function()
			return genv[name]
		end)
		if ok and v ~= nil then
			return v
		end
	end
	-- 2) ambient global identifier (works when funcs are plain globals)
	local ok2, v2 = pcall(function()
		return (_G :: any)[name]
	end)
	if ok2 and v2 ~= nil then
		return v2
	end
	return nil
end

local g_writefile = g("writefile")
local g_readfile = g("readfile")
local g_isfile = g("isfile")
local g_delfile = g("delfile")
local g_isfolder = g("isfolder")
local g_makefolder = g("makefolder")
local g_listfiles = g("listfiles")

Config.supported = type(g_writefile) == "function"
	and type(g_readfile) == "function"
	and type(g_isfile) == "function"

-- Surface what was detected so executor file-API gaps are obvious in the console.
print(("[coreui] config: supported=%s  writefile=%s readfile=%s isfile=%s listfiles=%s delfile=%s")
	:format(
		tostring(Config.supported),
		type(g_writefile), type(g_readfile), type(g_isfile),
		type(g_listfiles), type(g_delfile)
	))

-- Strip path separators so a config name can't escape its folder.
local function sanitize(name: string): string
	return (tostring(name):gsub("[^%w%-_ ]", "")):gsub("^%s*(.-)%s*$", "%1")
end

local function configsDir(folder: string): string
	return folder .. "/configs"
end

local function pathFor(folder: string, name: string): string
	return configsDir(folder) .. "/" .. sanitize(name) .. ".json"
end

local function ensureFolders(folder: string)
	if type(g_isfolder) ~= "function" or type(g_makefolder) ~= "function" then
		return
	end
	pcall(function()
		if not g_isfolder(folder) then
			g_makefolder(folder)
		end
		local cfg = configsDir(folder)
		if not g_isfolder(cfg) then
			g_makefolder(cfg)
		end
	end)
end

-- List saved config names (no path, no extension), sorted.
function Config.list(folder: string): { string }
	local names = {}
	if not Config.supported or type(g_listfiles) ~= "function" then
		return names
	end
	ensureFolders(folder)
	local ok, files = pcall(g_listfiles, configsDir(folder))
	if ok and type(files) == "table" then
		for _, path in files do
			local name = tostring(path):match("([^/\\]+)%.json$")
			if name then
				table.insert(names, name)
			end
		end
	end
	table.sort(names)
	return names
end

-- Serialize `data` to JSON and write it. Returns true on success.
function Config.save(folder: string, name: string, data: any): boolean
	if not Config.supported then
		return false
	end
	name = sanitize(name)
	if name == "" then
		return false
	end
	ensureFolders(folder)
	local ok, json = pcall(function()
		return HttpService:JSONEncode(data)
	end)
	if not ok then
		return false
	end
	return (pcall(g_writefile, pathFor(folder, name), json))
end

-- Read + decode a config. Returns the table, or nil if missing / corrupt.
function Config.load(folder: string, name: string): any?
	if not Config.supported then
		return nil
	end
	local path = pathFor(folder, name)
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return nil
	end
	local okRead, raw = pcall(g_readfile, path)
	if not okRead then
		return nil
	end
	local okDecode, data = pcall(function()
		return HttpService:JSONDecode(raw)
	end)
	if not okDecode then
		return nil
	end
	return data
end

function Config.delete(folder: string, name: string): boolean
	if not Config.supported or type(g_delfile) ~= "function" then
		return false
	end
	local path = pathFor(folder, name)
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return false
	end
	return (pcall(g_delfile, path))
end

-- Auto-load pointer: which config (if any) to apply on launch.
function Config.setAutoload(folder: string, name: string?)
	if not Config.supported then
		return
	end
	ensureFolders(folder)
	local path = folder .. "/autoload.txt"
	if name and sanitize(name) ~= "" then
		pcall(g_writefile, path, sanitize(name))
	elseif type(g_delfile) == "function" then
		local okExists, exists = pcall(g_isfile, path)
		if okExists and exists then
			pcall(g_delfile, path)
		end
	end
end

function Config.getAutoload(folder: string): string?
	if not Config.supported then
		return nil
	end
	local path = folder .. "/autoload.txt"
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return nil
	end
	local okRead, raw = pcall(g_readfile, path)
	if okRead and type(raw) == "string" and raw ~= "" then
		return raw
	end
	return nil
end

return Config

end

__modules['util.Context'] = function()
--!strict
-- util/Context.lua — the object threaded through every component.
--
-- Carries the live accent color (themeable via Window:SetAccent), an accent
-- subscription registry, the single-popover manager used by dropdowns and
-- color pickers (menus mount into a high-ZIndex overlay so they escape the
-- scrolling content's clipping), and the flag registry that backs config
-- save / load (any control given a `Flag` is captured by GetConfig/LoadConfig).

local Create = __require("util.Create")
local Tween = __require("util.Tween")
local Log = __require("util.Log")

local Context = {}
Context.__index = Context

export type Context = typeof(setmetatable(
	{} :: {
		Theme: any,
		Accent: Color3,
		AccentHover: Color3,
		overlay: Frame,
		Flags: { [string]: { handle: any, kind: string } },
		_consumers: { (Color3, Color3) -> () },
		_popover: { menu: Instance, catcher: Instance, conns: { RBXScriptConnection }, onClose: (() -> ())? }?,
	},
	Context
))

local function hover(accent: Color3): Color3
	return accent:Lerp(Color3.new(1, 1, 1), 0.3)
end

function Context.new(theme: any, overlay: Frame, accent: Color3): Context
	return setmetatable({
		Theme = theme,
		Accent = accent,
		AccentHover = hover(accent),
		overlay = overlay,
		Flags = {},
		_consumers = {},
		_popover = nil,
	}, Context)
end

-- Register a function recolored whenever the accent changes. Called once now
-- with the current accent so callers don't duplicate the initial paint. Returns
-- an unsubscribe function — transient consumers (e.g. toasts) must call it on
-- teardown or their dead closures pile up in the registry and fire on every
-- SetAccent forever.
function Context:RegisterAccent(fn: (Color3, Color3) -> ()): () -> ()
	table.insert(self._consumers, fn)
	fn(self.Accent, self.AccentHover)
	return function()
		local list = self._consumers
		for i = #list, 1, -1 do
			if list[i] == fn then
				table.remove(list, i)
				break
			end
		end
	end
end

function Context:SetAccent(color: Color3)
	self.Accent = color
	self.AccentHover = hover(color)
	for _, fn in self._consumers do
		fn(self.Accent, self.AccentHover)
	end
end

-- ── Flags / config ──────────────────────────────────────────────────────────
-- Each control kind serializes its value to a JSON-safe form and back. Color3 /
-- Enum.KeyCode aren't JSON-encodable, so they round-trip through hex / name.
local Codec: { [string]: { encode: (any) -> any, decode: (any) -> any } } = {
	toggle = {
		encode = function(v) return v == true end,
		decode = function(v) return v == true end,
	},
	slider = {
		encode = function(v) return v end,
		decode = function(v) return tonumber(v) or 0 end,
	},
	input = {
		encode = function(v) return tostring(v) end,
		decode = function(v) return tostring(v) end,
	},
	code = { -- raw editor text; stored verbatim like input
		encode = function(v) return tostring(v) end,
		decode = function(v) return tostring(v) end,
	},
	dropdown = {
		encode = function(v) return v end, -- string | { string } — both JSON-safe
		decode = function(v) return v end,
	},
	keybind = {
		encode = function(v) return (typeof(v) == "EnumItem" and v.Name) or "Unknown" end,
		decode = function(v)
			local ok, key = pcall(function()
				return (Enum.KeyCode :: any)[v]
			end)
			return (ok and key) or Enum.KeyCode.Unknown
		end,
	},
	colorpicker = {
		encode = function(v) return typeof(v) == "Color3" and v:ToHex() or tostring(v) end,
		decode = function(v)
			local ok, color = pcall(Color3.fromHex, v)
			return (ok and color) or Color3.new(1, 1, 1)
		end,
	},
	playerselect = { -- handle:Get() returns Player(s); persist as UserId(s), :Set resolves back
		encode = function(v)
			if type(v) == "table" then
				local ids = {}
				for _, p in v do
					if typeof(p) == "Instance" and p:IsA("Player") then
						table.insert(ids, p.UserId)
					end
				end
				return ids
			elseif typeof(v) == "Instance" and v:IsA("Player") then
				return v.UserId
			end
			return nil
		end,
		decode = function(v) return v end, -- number | { number } — handle:Set resolves ids live
	},
}

-- Register a stateful control's handle under `name` so config save/load can
-- read (:Get) and write (:Set) it. `kind` selects the codec. No-op without both.
function Context:RegisterFlag(name: string?, handle: any, kind: string?)
	if not name or not kind or not Codec[kind] or not handle then
		return
	end
	-- Two controls sharing a Flag silently overwrite each other in config
	-- save/load — the second wins and the first never persists. That's almost
	-- always a copy-paste slip, so surface it rather than let configs go stale.
	if self.Flags[name] then
		Log.warn("Flag", ('"%s" is registered twice — both controls share one config '
			.. "slot, so only the last will save/load. Give each a unique Flag."):format(name))
	end
	self.Flags[name] = { handle = handle, kind = kind }
end

-- Snapshot every flagged control into a JSON-safe table.
function Context:GetConfig(): { [string]: any }
	local data = {}
	for name, entry in self.Flags do
		local codec = Codec[entry.kind]
		local ok, value = pcall(function()
			return entry.handle:Get()
		end)
		if ok and codec then
			data[name] = codec.encode(value)
		end
	end
	return data
end

-- Apply a saved table back onto the flagged controls (fires their callbacks).
function Context:LoadConfig(data: { [string]: any })
	if type(data) ~= "table" then
		return
	end
	for name, raw in data do
		local entry = self.Flags[name]
		if entry then
			local codec = Codec[entry.kind]
			if codec then
				local okDecode, value = pcall(codec.decode, raw)
				if okDecode then
					pcall(function()
						entry.handle:Set(value)
					end)
				end
			end
		end
	end
end

-- ── Popovers ───────────────────────────────────────────────────────────────
function Context:ClosePopover()
	local p = self._popover
	if not p then
		return
	end
	self._popover = nil
	for _, conn in p.conns do
		conn:Disconnect()
	end
	p.catcher:Destroy()
	p.menu.Visible = false
	if p.onClose then
		p.onClose()
	end
end

-- Open `menu` directly under `anchor`, closing any other open popover first.
-- A full-overlay catcher button dismisses it on any outside click.
function Context:OpenPopover(menu: GuiObject, anchor: GuiObject, onClose: (() -> ())?)
	self:ClosePopover()

	local catcher = Create("TextButton", {
		Name = "Catcher",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 50,
		Parent = self.overlay,
	})
	menu.ZIndex = 60
	menu.Parent = self.overlay

	-- Place the menu under the anchor, but keep it inside the overlay (= window)
	-- bounds: clamp horizontally, and flip above the anchor when there isn't
	-- enough room below. The window clips descendants, so a menu that spilled
	-- off the edge would be cut off — this keeps it fully visible.
	local MARGIN = 8
	local GAP = 6
	local function place()
		local o = self.overlay.AbsolutePosition
		local os = self.overlay.AbsoluteSize
		local a = anchor.AbsolutePosition
		local asz = anchor.AbsoluteSize
		local msz = menu.AbsoluteSize

		local x = a.X - o.X
		x = math.clamp(x, MARGIN, math.max(MARGIN, os.X - msz.X - MARGIN))

		local below = (a.Y - o.Y) + asz.Y + GAP
		local above = (a.Y - o.Y) - msz.Y - GAP
		local y = below
		if below + msz.Y > os.Y - MARGIN and above >= MARGIN then
			y = above -- not enough room below → open upward
		end
		y = math.clamp(y, MARGIN, math.max(MARGIN, os.Y - msz.Y - MARGIN))

		menu.Position = UDim2.fromOffset(x, y)
	end
	place()
	menu.Visible = true

	-- Fade the menu in. CanvasGroup renders its descendants to one buffer, so a
	-- single GroupTransparency tween brings the whole popover up together.
	if menu:IsA("CanvasGroup") then
		menu.GroupTransparency = 1
		Tween.play(menu, Tween.Pop, { GroupTransparency = 0 })
	end

	-- Re-place when the anchor moves, when the menu's auto-size settles, or when
	-- the window resizes.
	local conns = {
		anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(place),
		menu:GetPropertyChangedSignal("AbsoluteSize"):Connect(place),
		self.overlay:GetPropertyChangedSignal("AbsoluteSize"):Connect(place),
	}
	self._popover = { menu = menu, catcher = catcher, conns = conns, onClose = onClose }
	catcher.Activated:Connect(function()
		self:ClosePopover()
	end)
end

function Context:IsOpen(menu: GuiObject): boolean
	return self._popover ~= nil and self._popover.menu == menu
end

return Context

end

__modules['util.Create'] = function()
--!strict
-- util/Create.lua — tiny instance factory + common UI helpers.
--
--   Create("Frame", { Size = ..., Parent = ... }, { childA, childB })
--
-- Props are assigned in order; `Parent` is always applied last so children
-- exist before the instance enters the tree. Helper constructors (corner,
-- stroke, padding, listLayout) cover the boilerplate instances used everywhere.

local Create = setmetatable({}, {
	__call = function(_, className: string, props: { [string]: any }?, children: { Instance }?): any
		local inst = Instance.new(className)
		local parent
		if props then
			for key, value in props do
				if key == "Parent" then
					parent = value
				else
					(inst :: any)[key] = value
				end
			end
		end
		if children then
			for _, child in children do
				child.Parent = inst
			end
		end
		inst.Parent = parent
		return inst
	end,
})

function Create.corner(radius: number): UICorner
	return Create("UICorner", { CornerRadius = UDim.new(0, radius) })
end

function Create.stroke(color: Color3, thickness: number?): UIStroke
	return Create("UIStroke", {
		Color = color,
		Thickness = thickness or 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		-- Round joins trace the UICorner arc smoothly instead of cutting it with
		-- mitred corners, which is what made bordered cards/controls look jagged.
		LineJoinMode = Enum.LineJoinMode.Round,
	})
end

function Create.padding(top: number, right: number?, bottom: number?, left: number?): UIPadding
	right = right or top
	bottom = bottom or top
	left = left or right
	return Create("UIPadding", {
		PaddingTop = UDim.new(0, top),
		PaddingRight = UDim.new(0, right),
		PaddingBottom = UDim.new(0, bottom),
		PaddingLeft = UDim.new(0, left),
	})
end

function Create.listLayout(props: { [string]: any }?): UIListLayout
	local layout = Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		FillDirection = Enum.FillDirection.Vertical,
	})
	if props then
		for key, value in props do
			(layout :: any)[key] = value
		end
	end
	return layout
end

return Create

end

__modules['util.Log'] = function()
--!strict
-- util/Log.lua — one place every coreui diagnostic flows through, so the format
-- stays uniform and the library explains a mistake instead of throwing a bare
-- "attempt to index nil value" three frames deep in a bundled chunk.
--
-- Policy:
--   * fail  — the call genuinely can't proceed (wrong TYPE for a required arg).
--             Raised with level 0 so the executor console shows our clean
--             "[coreui] Slider "Speed": ..." text, not a bundle file:line prefix.
--   * warn  — a recoverable mistake (bad enum value, out-of-range index, a
--             missing option we can default). We say what happened + what we did
--             and keep building, so one typo never blanks the whole menu.
--
-- `where` is a short human label for the call site, e.g. `Log.where("Slider",
-- opts.Name)` → `Slider "Speed"`. Keep messages actionable: name the field, the
-- value we got, and the fix.

local PREFIX = "[coreui]"

local Log = {}

-- Build a "Control \"Name\"" label for messages. Falls back to just the control
-- name when the field is anonymous.
function Log.where(control: string, name: any?): string
	if type(name) == "string" and name ~= "" then
		return ('%s "%s"'):format(control, name)
	end
	return control
end

-- Hard stop. Never returns.
function Log.fail(where: string, msg: string): never
	return error(("%s %s: %s"):format(PREFIX, where, msg), 0)
end

-- Soft warning — lands in the executor console (warn channel), build continues.
function Log.warn(where: string, msg: string)
	warn(("%s %s: %s"):format(PREFIX, where, msg))
end

-- fail(where, msg) unless `cond` is truthy. Returns cond so it can be inlined.
function Log.assert(cond: any, where: string, msg: string): any
	if not cond then
		Log.fail(where, msg)
	end
	return cond
end

-- Type guard for a single option field. `accepts` is one type name or a list of
-- them (as returned by `typeof`, so "table"/"number"/"function"/"Color3"/
-- "EnumItem"/…). `nil`/absent always passes — callers validate required-ness
-- separately. Fails with a message naming the field, the accepted type(s), and
-- what we actually got.
function Log.field(where: string, field: string, value: any, accepts: string | { string })
	if value == nil then
		return value
	end
	local got = typeof(value)
	local list = type(accepts) == "table" and accepts or { accepts :: string }
	for _, want in list do
		if got == want then
			return value
		end
	end
	Log.fail(where, ("%s must be a %s, got %s"):format(field, table.concat(list, " or "), got))
	return value
end

return Log

end

__modules['util.Tween'] = function()
--!strict
-- util/Tween.lua — shared tween presets. All UI motion is ease-out ~0.12–0.18s.

local TweenService = game:GetService("TweenService")

local Tween = {}

local OUT = Enum.EasingStyle.Quad
local DIR = Enum.EasingDirection.Out

Tween.Fast   = TweenInfo.new(0.12, OUT, DIR) -- hovers, borders
Tween.Normal = TweenInfo.new(0.18, OUT, DIR) -- toggle, chevron
Tween.Spin   = TweenInfo.new(0.26, Enum.EasingStyle.Back, DIR) -- collapse chevrons (slight overshoot)
Tween.Spring = TweenInfo.new(0.28, Enum.EasingStyle.Back, DIR) -- knobs / pops that should overshoot
Tween.Press  = TweenInfo.new(0.09, Enum.EasingStyle.Quad, DIR) -- button tap squash
Tween.Pop    = TweenInfo.new(0.16, Enum.EasingStyle.Back, DIR) -- popovers / window in
Tween.Slide  = TweenInfo.new(0.22, Enum.EasingStyle.Quint, DIR) -- panel collapse/expand, search reveal (smooth, no overshoot)
Tween.MenuOut = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In) -- window leaving (accelerate + fade away)
Tween.Toast  = TweenInfo.new(0.22, Enum.EasingStyle.Quint, DIR)
Tween.ToastOut = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In)

function Tween.play(instance: Instance, info: TweenInfo, goals: { [string]: any }): Tween
	local tween = TweenService:Create(instance, info, goals)
	tween:Play()
	return tween
end

return Tween

end

return __require("")